mapper.select:
SELECT 
FROM TBL_TREASURY_SEAL_USAGE_LOGS
WHERE 1=1

    AND SEALID = #{params.sealId}


    AND BUSINESSTYPE LIKE CONCAT('%', #{params.businessType}, '%')


    AND BUSINESSNO LIKE CONCAT('%', #{params.businessNo}, '%')


    AND USERNAME LIKE CONCAT('%', #{params.userName}, '%')


    AND USAGESTATUS = #{params.usageStatus}


    AND USAGEDATE >= #{params.startDate}


    AND USAGEDATE <= #{params.endDate}


    AND ORGID = #{params.orgId}

ORDER BY USAGEDATE DESC

