mapper.select:
SELECT COUNT(*)
FROM TBL_TREASURY_SEAL_USAGE_LOGS
WHERE SEALID = #{sealId}

SELECT COUNT(*)
FROM TBL_TREASURY_SEAL_USAGE_LOGS
WHERE DATE(USAGEDATE) = #{usageDate}

SELECT FROM TBL_TREASURY_SEAL_USAGE_LOGS WHERE DATE(USAGEDATE) = CURRENT_DATE
AND ORGID = #{orgId}
ORDER BY USAGEDATE DESC

SELECT FROM TBL_TREASURY_SEAL_USAGE_LOGS WHERE USAGESTATUS = 'PENDING'
AND ORGID = #{orgId}
ORDER BY USAGEDATE ASC
